"""Custom fused CUDA top-k (single kernel launch per call).

Algorithm:
  - grid = batch * numseg blocks. Each block loads a SEG-sized segment of a
    row, packs (monotonic fp32 key << 32) | index into uint64 keys in shared
    memory, bitonic-sorts them ascending, and writes its top-k keys to a
    global workspace.
  - The last block to finish a row (atomic counter) reloads all candidate
    keys for the row, bitonic-sorts them in shared memory, and writes the
    final top-k values (fp32) and indices (int64), sorted descending.
"""

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

OP_TYPE = "topk"
SUPPORTED_PRECISIONS = ["fp32"]
HARDWARE_REQUIRED = ["RTX_PRO_6000", "H100", "B200"]

_CPP_SRC = "std::vector<torch::Tensor> topk_forward(torch::Tensor x, int64_t k);"

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <algorithm>
#include <vector>

__device__ __forceinline__ unsigned long long pack_key(float v, unsigned int idx) {
    unsigned int u = __float_as_uint(v);
    u ^= (u & 0x80000000u) ? 0xFFFFFFFFu : 0x80000000u;
    return ((unsigned long long)u << 32) | (unsigned long long)idx;
}

__device__ __forceinline__ float unpack_val(unsigned long long key) {
    unsigned int u = (unsigned int)(key >> 32);
    u = (u & 0x80000000u) ? (u ^ 0x80000000u) : ~u;
    return __uint_as_float(u);
}

__device__ __forceinline__ void bitonic_sort(unsigned long long* skeys, int N, int tid, int nthreads) {
    for (int size = 2; size <= N; size <<= 1) {
        for (int stride = size >> 1; stride > 0; stride >>= 1) {
            for (int i = tid; i < N; i += nthreads) {
                int j = i ^ stride;
                if (j > i) {
                    bool up = ((i & size) == 0);
                    unsigned long long a = skeys[i], b = skeys[j];
                    if ((up && a > b) || (!up && a < b)) {
                        skeys[i] = b;
                        skeys[j] = a;
                    }
                }
            }
            __syncthreads();
        }
    }
}

extern "C" __global__ void topk_fused(
    const float* __restrict__ x,
    unsigned long long* __restrict__ ws,
    int* __restrict__ counters,
    float* __restrict__ out_v,
    long long* __restrict__ out_i,
    int n, int k, int numseg, int SEG, int N2)
{
    extern __shared__ unsigned long long skeys[];
    const int row = blockIdx.x / numseg;
    const int seg = blockIdx.x % numseg;
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;

    // Load segment, pack keys, pad with 0 (smaller than any real key).
    const float* xrow = x + (long long)row * n;
    for (int e = tid; e < SEG; e += nthreads) {
        int off = seg * SEG + e;
        unsigned long long key = 0ULL;
        if (off < n) key = pack_key(xrow[off], (unsigned int)off);
        skeys[e] = key;
    }
    __syncthreads();

    bitonic_sort(skeys, SEG, tid, nthreads);

    // Segment top-k (largest k sit at the end after ascending sort).
    unsigned long long* wseg = ws + ((long long)row * numseg + seg) * k;
    for (int j = tid; j < k; j += nthreads) {
        wseg[j] = skeys[SEG - 1 - j];
    }
    __syncthreads();

    if (tid == 0) {
        __threadfence();
        int old = atomicAdd(&counters[row], 1);
        __threadfence();
        skeys[0] = (old == numseg - 1) ? 1ULL : 0ULL;
    }
    __syncthreads();
    const bool last = (skeys[0] == 1ULL);
    __syncthreads();
    if (!last) return;

    // Merge: sort all candidate keys for this row.
    const int C = numseg * k;
    const unsigned long long* wrow = ws + (long long)row * C;
    for (int e = tid; e < N2; e += nthreads) {
        skeys[e] = (e < C) ? wrow[e] : 0ULL;
    }
    __syncthreads();

    bitonic_sort(skeys, N2, tid, nthreads);

    for (int j = tid; j < k; j += nthreads) {
        unsigned long long key = skeys[N2 - 1 - j];
        out_v[(long long)row * k + j] = unpack_val(key);
        out_i[(long long)row * k + j] = (long long)(unsigned int)(key & 0xFFFFFFFFULL);
    }
}

std::vector<torch::Tensor> topk_forward(torch::Tensor x, int64_t k) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be fp32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    auto xc = x.contiguous();

    const int64_t batch = xc.size(0);
    const int64_t n = xc.size(1);
    TORCH_CHECK(k > 0 && k <= 1024, "k out of supported range");

    int64_t SEG = 1024;
    int64_t numseg = (n + SEG - 1) / SEG;
    while (numseg * k > 4096 && SEG < n) {
        SEG *= 2;
        numseg = (n + SEG - 1) / SEG;
    }
    int64_t C = numseg * k;
    int64_t N2 = 1;
    while (N2 < C) N2 *= 2;

    auto opts = xc.options();
    auto out_v = torch::empty({batch, k}, opts.dtype(torch::kFloat32));
    auto out_i = torch::empty({batch, k}, opts.dtype(torch::kInt64));
    auto ws = torch::empty({batch * C}, opts.dtype(torch::kInt64));
    auto counters = torch::zeros({batch}, opts.dtype(torch::kInt32));

    const int threads = 256;
    const dim3 grid((unsigned int)(batch * numseg));
    const size_t smem = (size_t)std::max<int64_t>(SEG, N2) * sizeof(unsigned long long);

    auto stream = at::cuda::getCurrentCUDAStream();
    if (smem > 48 * 1024) {
        cudaFuncSetAttribute(topk_fused, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
    }
    topk_fused<<<grid, threads, smem, stream>>>(
        xc.data_ptr<float>(),
        reinterpret_cast<unsigned long long*>(ws.data_ptr<int64_t>()),
        counters.data_ptr<int>(),
        out_v.data_ptr<float>(),
        reinterpret_cast<long long*>(out_i.data_ptr<int64_t>()),
        (int)n, (int)k, (int)numseg, (int)SEG, (int)N2);

    return {out_v, out_i};
}
"""

_ext = load_inline(
    name="topk_fused_ext",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["topk_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class Model(nn.Module):
    """Top-k over the last dim of a 2D tensor via a custom fused CUDA kernel."""

    def __init__(self, batch: int, n: int, k: int):
        super().__init__()
        self.batch, self.n, self.k = batch, n, k
        self.register_buffer("_dummy", torch.zeros(1))

    def forward(self, x: torch.Tensor):
        out = _ext.topk_forward(x, self.k)
        return out[0], out[1]


